  as select from I_AnySource as AnyAlias

{
  key AnyAlias.AnyKeyField,

      currency_conversion(
       amount => AnyAlias.Amount,
        source_currency =>AnyAlias.Currency,
     target_currency =>$parameters.P_DisplayCurrency,
